#!/bin/sh /etc/rc.common

# Needs to start before network
START=19
start() {
    ip link add dev ecd0 type veth peer name ecd1
    ip link set ecd0 up
    ip link set ecd1 up
    brctl addif br-lan ecd0 
}

{
  "user": "appService",
  "access": {
    "apcloud_event": {
      "methods": [
        "update"
      ]
    }
  },
  "subscribe": [
    "mesh"
  ],
  "listen": [
    "mesh",
    "ubus.object.add",
    "ubus.object.remove"
  ],
  "send": [
    "apcloud_event"
  ],
  "publish": [
    "apcloud_event"
  ]
}

